// Catálogo de "Sabores de España" — 207 recetas españolas tradicionales,
// repartidas en 11 categorías (ver src/lib/categories.js).
//
// Este archivo es el contenido de fábrica de la app: se carga siempre,
// incluso sin backend configurado. Desde /admin se puede editar el texto y
// cambiar la foto de cada receta sin tocar código — esos cambios se guardan
// aparte (Redis) y se combinan con este catálogo al mostrarse.
//
// Cómo sumar una receta nueva: copiá el bloque receta({...}) más parecido y
// completá los campos. `slug` e `id` se generan solos a partir del nombre.

let uid = 0;
const next = () => `r${++uid}`;

function receta({
  nombre,
  categoria,
  region = '',
  descripcion,
  imagen = '',
  tiempoPrepMinutos,
  tiempoCoccionMinutos = 0,
  dificultad, // 'Fácil' | 'Media' | 'Difícil'
  porciones,
  ingredientes,
  pasos,
  consejos = [],
  conservacion = 'Se conserva en la nevera, en un recipiente hermético, hasta 2-3 días.',
  destacada = false,
  publicada = true,
}) {
  const slug = nombre
    .toLowerCase()
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/(^-|-$)/g, '');
  return {
    id: next(),
    slug,
    nombre,
    categoria,
    region,
    descripcion,
    imagen,
    tiempoPrepMinutos,
    tiempoCoccionMinutos,
    tiempoTotalMinutos: tiempoPrepMinutos + tiempoCoccionMinutos,
    dificultad,
    porciones,
    ingredientes,
    pasos,
    consejos,
    conservacion,
    destacada,
    publicada,
  };
}

